# List of 2-digit good numbers provided by W1
L_2D = {12, 13, 14, 15, 16, 17, 18, 19, 21, 24, 25, 26, 28, 31, 32, 35, 36, 39, 41, 42, 45, 48, 51, 52, 61, 62, 63, 64, 65, 71, 72, 75, 81, 82, 84, 85, 91, 92, 93, 95, 96}

def is_good_3_digit(m):
    """
    Checks if a 3-digit number m=abc is 'good' based on the definition.
    m must have distinct nonzero digits.
    """
    s = str(m)
    if len(s) != 3:
        return False

    a, b, c = int(s[0]), int(s[1]), int(s[2])

    # Ensure digits are distinct and nonzero (although iteration should handle this)
    if len({a, b, c}) != 3 or 0 in {a, b, c}:
        return False

    # Check the three possible removals

    # Case 1: Remove c -> m' = ab
    m_prime_ab = 10*a + b
    if m_prime_ab in L_2D:
        # Condition: m' | m
        if m % m_prime_ab == 0:
            return True

    # Case 2: Remove b -> m' = ac
    m_prime_ac = 10*a + c
    if m_prime_ac in L_2D:
        # Condition: m' | m
        if m % m_prime_ac == 0:
            return True

    # Case 3: Remove a -> m' = bc
    m_prime_bc = 10*b + c
    if m_prime_bc in L_2D:
        # Condition: m' | m
        if m % m_prime_bc == 0:
            return True

    return False

# Systematic search starting from the largest possible 3-digit number (987)
# Digits must be distinct and nonzero.
largest_good_number = None

# Iterate downwards from 987
for m in range(999, 99, -1):
    s = str(m)
    if len(s) != 3:
        continue

    a, b, c = int(s[0]), int(s[1]), int(s[2])

    # Skip if digits are not distinct or if any digit is zero
    if a == b or a == c or b == c or a == 0 or b == 0 or c == 0:
        continue

    if is_good_3_digit(m):
        largest_good_number = m
        break

if largest_good_number:
    print(f"Largest 3-digit good number found: {largest_good_number}")
else:
    print("No 3-digit good number found.")
